{
  "apiVersion": 1,
  "type": "component.batch",
  "data": {
    "count": 3,
    "results": [
      {
        "selector": "ChatSendButton",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatSendButton",
            "subComponentOf": "Chat",
            "displayName": "Chat Send Button",
            "isHiddenFromOverview": true,
            "description": "Circular send/stop toggle button for the chat composer. Place it inside ChatComposer where it reads context automatically: no wiring needed. When streaming starts, the button switches from a primary send icon to a secondary stop icon. Override any context value via props for standalone or custom usage.",
            "props": [
              {
                "name": "isStopShown",
                "type": "boolean",
                "description": "Whether the stop button is shown. Defaults to context value."
              },
              {
                "name": "isDisabled",
                "type": "boolean",
                "description": "Whether the send button is disabled. Defaults to !canSend from context."
              },
              {
                "name": "onSend",
                "type": "() => void",
                "description": "Called when the user clicks send. Defaults to context onSubmit."
              },
              {
                "name": "onStop",
                "type": "() => void",
                "description": "Called when the user clicks stop during streaming. Defaults to context onStop."
              },
              {
                "name": "sendIcon",
                "type": "ReactNode",
                "description": "Custom icon for the send state. Defaults to arrowUp from icon registry.",
                "slotElements": [
                  {
                    "__element": "Icon",
                    "props": {
                      "icon": "check",
                      "size": "sm"
                    }
                  }
                ]
              },
              {
                "name": "stopIcon",
                "type": "ReactNode",
                "description": "Custom icon for the stop state. Defaults to stop from icon registry.",
                "slotElements": [
                  {
                    "__element": "Icon",
                    "props": {
                      "icon": "check",
                      "size": "sm"
                    }
                  }
                ]
              },
              {
                "name": "size",
                "type": "'sm' | 'md'",
                "description": "Button size.",
                "default": "'md'"
              },
              {
                "name": "xstyle",
                "type": "StyleXStyles",
                "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value: not an inline style object like style={{}}."
              }
            ],
            "usage": {
              "description": "Use ChatSendButton as ChatComposer’s send control when the action should switch between sending and stopping. Inside ChatComposer it reads readiness, streaming state, and action callbacks from context; standalone usage supplies those values explicitly.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Place ChatSendButton inside ChatComposer when its readiness and send or stop lifecycle should follow composer context."
                },
                {
                  "guidance": true,
                  "description": "For standalone use, provide the state and matching onSend or onStop callback explicitly."
                },
                {
                  "guidance": true,
                  "description": "Keep the translated Send or Stop accessible name intact when supplying custom icon artwork; the icon is decorative and must not be the only name source."
                },
                {
                  "guidance": false,
                  "description": "Do not render the stop state without a working onStop callback from props or ChatComposer context."
                },
                {
                  "guidance": false,
                  "description": "Do not expect isDisabled to disable the stop action; it applies only to the send state."
                }
              ],
              "anatomy": [
                {
                  "name": "Action button",
                  "required": true,
                  "description": "Circular icon-only Button that exposes the translated Send or Stop name and carries the chat-send-button theme target."
                }
              ]
            },
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatSystemMessage",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatSystemMessage",
            "subComponentOf": "Chat",
            "displayName": "Chat System Message",
            "description": "Centered system message for non-sender content like date separators, membership changes, and status notices. It is not a chat bubble; it has no avatar, no alignment, and no sender context. Use the divider variant for temporal breaks and default for inline status updates.",
            "props": [
              {
                "name": "children",
                "type": "ReactNode",
                "description": "System message content: factual text or React content such as a date, join/leave notice, or status change. Long default content wraps within the available width.",
                "required": true
              },
              {
                "name": "variant",
                "type": "'default' | 'divider'",
                "description": "Visual variant. 'default' renders centered text. 'divider' adds horizontal lines on each side via Divider: use for date separators and section breaks.",
                "default": "'default'"
              },
              {
                "name": "icon",
                "type": "ReactNode",
                "description": "Optional caller-provided icon content. Rendered before the message in the default variant; the divider variant currently does not render it. Wrap in Icon for consistent sizing.",
                "slotElements": [
                  {
                    "__element": "Icon",
                    "props": {
                      "icon": "check",
                      "size": "sm"
                    }
                  }
                ]
              },
              {
                "name": "xstyle",
                "type": "StyleXStyles",
                "description": "StyleX styles for layout customization. Must be a stylex.create() value: not an inline style object like style={{}}."
              }
            ],
            "theming": {
              "targets": [
                {
                  "className": "astryx-chat-system-message",
                  "visualProps": [
                    "variant"
                  ]
                }
              ]
            },
            "usage": {
              "description": "Use ChatSystemMessage for concise, non-sender content inside a chat transcript. Choose the default variant for factual status notices and the divider variant for date or section breaks. Long default content wraps within the available width. It carries no live role: inside a ChatMessageList, the log announces new notices. The divider branch includes a labelled separator.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Keep the visible message concise and self-contained so it remains understandable without an icon."
                },
                {
                  "guidance": true,
                  "description": "Use the divider variant for temporal or section boundaries and the default variant for factual status notices."
                },
                {
                  "guidance": false,
                  "description": "Use ChatSystemMessage for sender-authored content; use ChatMessage and ChatMessageBubble instead."
                },
                {
                  "guidance": false,
                  "description": "Use caller-provided icon artwork as the only source of meaning; the visible message must carry the same information."
                }
              ],
              "anatomy": [
                {
                  "name": "System message",
                  "required": true,
                  "description": "The noninteractive status row that carries the chat-system-message theme target."
                },
                {
                  "name": "Content",
                  "required": true,
                  "description": "The concise caller-provided message or divider label."
                },
                {
                  "name": "Icon content",
                  "required": false,
                  "description": "Rendered before the message in the default variant; the divider variant currently does not render it."
                },
                {
                  "name": "Divider",
                  "required": false,
                  "description": "A labelled horizontal Divider rendered by the divider variant."
                }
              ]
            },
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      },
      {
        "selector": "ChatTokenizedText",
        "status": "found",
        "result": {
          "type": "component.detail",
          "package": "@astryxdesign/core",
          "data": {
            "name": "ChatTokenizedText",
            "subComponentOf": "Chat",
            "displayName": "Chat Tokenized Text",
            "isHiddenFromOverview": true,
            "description": "Renders a text string with token patterns replaced by inline token content. Wrap any message body inside ChatMessageBubble to turn raw @mentions, #tags, or /commands into styled content. When no non-empty token matches or none are provided, the text renders as-is, so you can use ChatTokenizedText unconditionally on every message.",
            "props": [
              {
                "name": "children",
                "type": "string",
                "description": "The plain text message containing serialized token values. Patterns matching a token's value are replaced with inline token content.",
                "required": true
              },
              {
                "name": "tokens",
                "type": "ChatComposerToken[]",
                "description": "Token definitions using the same type as composer input. Each non-empty value is matched literally. Empty values are ignored. Structured tokens render a Badge, while custom tokens render caller content."
              },
              {
                "name": "xstyle",
                "type": "StyleXStyles",
                "description": "StyleX styles for the root text wrapper. Must be a stylex.create() value: not an inline style object like style={{}}."
              }
            ],
            "theming": {
              "targets": [
                {
                  "className": "astryx-chat-tokenized-text"
                }
              ]
            },
            "usage": {
              "description": "Use ChatTokenizedText inside a chat message when stored plain text contains serialized token values that should be projected as inline badges or caller-rendered token content. Unmatched text is preserved exactly and empty token values are ignored so rendering always finishes.",
              "bestPractices": [
                {
                  "guidance": true,
                  "description": "Reuse the same token definitions for composer insertion and message rendering so serialized values and visible labels stay aligned."
                },
                {
                  "guidance": true,
                  "description": "Use non-empty, stable serialized values so every definition identifies real message text."
                },
                {
                  "guidance": false,
                  "description": "Use token labels as a substitute for the surrounding message text; the complete message must remain understandable in reading order."
                },
                {
                  "guidance": false,
                  "description": "Put component-owned interaction or accessibility behavior inside a custom token renderer; custom token content remains caller owned."
                }
              ],
              "anatomy": [
                {
                  "name": "Tokenized text",
                  "required": true,
                  "description": "The inline root that preserves unmatched text and carries the chat-tokenized-text theme target."
                },
                {
                  "name": "Rendered token",
                  "required": false,
                  "description": "Inline token content rendered by Badge for structured tokens or by the caller for custom tokens."
                }
              ]
            },
            "package": "@astryxdesign/core",
            "import": "@astryxdesign/core/Chat",
            "sourceAvailable": true
          }
        }
      }
    ]
  },
  "meta": {
    "answeredBy": {
